#pragma once
#include "engine/state_machine.hpp"
#include <iomanip>
#include <sstream>
#include <stdexcept>
// Browser transport only. Runtime schemas, queues and validation remain portable.
namespace engine::aiEventBrowser {
inline void value(std::ostream& out,const AiValue& value){std::visit([&](const auto& x){using T=std::decay_t<decltype(x)>;if constexpr(std::is_same_v<T,bool>)out<<(x?"true":"false");else if constexpr(std::is_same_v<T,Vec3>)out<<'['<<x.x<<','<<x.y<<','<<x.z<<']';else if constexpr(std::is_same_v<T,std::string>)out<<std::quoted(x);else out<<x;},value);}
inline void definitions(std::ostream& out,const std::vector<AiEventDefinition>& definitions){out<<'[';bool comma=false;for(const auto& e:definitions){if(comma)out<<',';comma=true;out<<"{\"key\":"<<std::quoted(e.key)<<",\"parameters\":[";bool sep=false;for(const auto& p:e.parameters){if(sep)out<<',';sep=true;out<<"{\"key\":"<<std::quoted(p.key)<<",\"type\":"<<int(p.type)<<",\"minimum\":"<<p.minimum<<",\"maximum\":"<<p.maximum<<",\"initial\":";value(out,p.initial);out<<'}';}out<<"]}";}out<<']';}
template<class T>void diagnostics(std::ostream& out,const T& runtime){out<<"{\"pending\":"<<runtime.pendingEvents()<<",\"scopes\":[";bool comma=false;for(auto state:runtime.activePath()){if(comma)out<<',';comma=true;auto s=runtime.eventScope(state);out<<"{\"state\":"<<s.state<<",\"instance\":\""<<s.instance<<"\",\"activation\":\""<<s.activation<<"\"}";}out<<"],\"history\":[";comma=false;for(const auto& r:runtime.eventHistory()){if(comma)out<<',';comma=true;static constexpr const char* outcomes[]={"queued","consumed","unmatched","canceled","overflow","stale-scope","stopped"};out<<"{\"key\":"<<std::quoted(r.event.key)<<",\"sequence\":\""<<r.sequence<<"\",\"outcome\":\""<<outcomes[int(r.outcome)]<<"\",\"transition\":"<<(r.transition?std::to_string(*r.transition):"null")<<",\"seconds\":"<<r.simulationSeconds<<",\"parameters\":{";bool sep=false;for(const auto&[k,v]:r.event.parameters){if(sep)out<<',';sep=true;out<<std::quoted(k)<<':';value(out,v);}out<<"}}";}out<<"]}";}
inline std::pair<AiEvent,std::optional<AiEventScope>> request(std::string_view bytes){std::istringstream in{std::string(bytes)};in.imbue(std::locale::classic());AiEvent event;std::size_t count=0;if(!(in>>std::quoted(event.key)>>count)||count>8)throw std::invalid_argument("Invalid AI event request");for(std::size_t i=0;i<count;++i){std::string key;if(!(in>>std::quoted(key)))throw std::invalid_argument("Invalid AI event parameter");auto value=readAiValue(in);if(!event.parameters.emplace(key,std::move(value)).second)throw std::invalid_argument("Duplicate AI event parameter");}unsigned scoped=0;std::optional<AiEventScope> scope;if(!(in>>scoped)||scoped>1)throw std::invalid_argument("Invalid AI event scope");if(scoped){AiEventScope s;if(!(in>>s.instance>>s.activation>>s.state))throw std::invalid_argument("Invalid AI event token");scope=s;}in>>std::ws;if(!in.eof())throw std::invalid_argument("Unexpected AI event payload suffix");return {std::move(event),scope};}
}
